def run(arm, object, direction, distance_m, **_):
    objects = ['red_block', 'green_block', 'blue_block']
    arm.close()  # Close gripper in preparation for potential contact
    for obj in objects:
        pos = arm.pos(obj)
        top_z = arm.top(obj) + 0.02
        hover = [pos[0], pos[1], top_z]
        arm.move_to(hover)
        arm.move_to([pos[0], pos[1], arm.top(obj)], yaw_deg=0)
        if direction == 'forward':
            arm.move_to([pos[0] - distance_m, pos[1], arm.top(obj)], yaw_deg=0)
        elif direction == 'back':
            arm.move_to([pos[0] + distance_m, pos[1], arm.top(obj)], yaw_deg=0)
        elif direction == 'left':
            arm.move_to([pos[0], pos[1] + distance_m, arm.top(obj)], yaw_deg=0)
        elif direction == 'right':
            arm.move_to([pos[0], pos[1] - distance_m, arm.top(obj)], yaw_deg=0)
        arm.move_to(hover)
    arm.release()  # Release any residual grip
